import { ICON_PATHS } from "./iconPaths";

/**
 * The staff app's icon set: Phosphor's shapes (2026-10-23 redesign; was
 * Lucide). Softer geometry closer to Apple's SF Symbols, with a matching
 * FILLED form for the selected item, the way iOS and macOS mark it (`filled`).
 *
 * The shapes live in iconPaths.ts as plain SVG paths, generated by
 * scripts/build-icons.mjs with ONLY the weights we draw (regular, fill, a
 * little bold) -- Phosphor's own components carry all six weights per icon
 * and pushed pages over the bundle budget. To add an icon, list it in that
 * script and re-run it. Plain SVG, so this works in server and client
 * components alike.
 *
 * Icons render in `currentColor`. A few call sites still pass an emoji string;
 * `Icon` maps those via EMOJI_MAP, and an unmapped emoji renders itself.
 * The public website keeps its own set (modules/site/components/SiteIcon.tsx).
 */
export type IconName = keyof typeof ICON_PATHS;

/** Emoji still used at a few call sites -> its icon. */
const EMOJI_MAP: Record<string, IconName> = {
  "📦": "package",
  "📅": "calendar",
  "🗓": "calendar",
  "🔨": "hammer",
  "🧵": "needle",
  "✅": "check-circle",
  "⏰": "clock",
  "🕓": "history",
  "⚠": "alert",
  "💳": "card",
  "💰": "wallet",
  "🛒": "cart",
  "📊": "bar-chart",
  "📈": "trending-up",
  "👥": "users",
  "👤": "user",
  "🛡": "shield",
  "🧾": "receipt",
  "🧑‍💼": "briefcase",
  "🔎": "search",
  "🖼": "image",
  "🔧": "wrench",
  "🛠": "wrench",
  "📝": "edit",
  "👩‍🎨": "palette",
  "👗": "shirt",
  "🏭": "factory",
  "📱": "qr",
  "📌": "clipboard",
  "📋": "list",
  "✦": "sparkles",
  "🏷": "printer",
  "🖨": "printer",
  "🗂": "columns",
  "⚙": "cog",
  "✋": "hand",
  "⬇": "download",
  "›": "chevron-right",
  "🎨": "palette",
  "✂": "scissors",
};

export function Icon({
  name,
  emoji,
  size = 20,
  className = "",
  strokeWidth,
  filled = false,
}: {
  name?: IconName;
  /** A string to resolve to an icon: either an icon name (e.g. "bar-chart") or an emoji (e.g. "📊"). Falls back to the emoji itself if unmapped. */
  emoji?: string;
  size?: number;
  className?: string;
  /** Kept for older call sites: 2.25 or more draws the bold weight where one is generated (small checkmarks). */
  strokeWidth?: number;
  /** The selected / active form (e.g. the current nav item), like SF Symbols' `.fill`. */
  filled?: boolean;
}) {
  // Try the string as an icon name first, then as an emoji (dropping the VS16
  // variation selector so "⚠️" matches "⚠", etc.).
  const resolved: IconName | undefined =
    name ?? (emoji ? (emoji in ICON_PATHS ? (emoji as IconName) : EMOJI_MAP[emoji.replace(/️/g, "")]) : undefined);

  if (!resolved) {
    return emoji ? <span className={className}>{emoji}</span> : null;
  }

  const shape: { regular: string[]; fill: string[]; bold?: string[] } = ICON_PATHS[resolved];
  const paths = filled ? shape.fill : strokeWidth !== undefined && strokeWidth >= 2.25 && shape.bold ? shape.bold : shape.regular;
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 256 256"
      fill="currentColor"
      className={`inline-block shrink-0 ${className}`}
      aria-hidden="true"
      focusable="false"
    >
      {paths.map((d) => (
        <path key={d} d={d} />
      ))}
    </svg>
  );
}
